import React, { FC } from 'react';

// Визначаємо інтерфейс SearchOptions тут, якщо він не доступний з іншого файлу
interface SearchOptions {
  price: string | null;
  rating: number | null;
  country: string | null;
  term: string;
}

export interface FilterMenuProps {
  searchOptions: SearchOptions;
  setSearchOptions: React.Dispatch<React.SetStateAction<SearchOptions>>;
  priceOptions: string[];
  ratingOptions: number[];
  countryOptions: string[];
}

export const FilterMenu: FC<FilterMenuProps> = ({ 
  searchOptions, 
  setSearchOptions, 
  priceOptions, 
  ratingOptions, 
  countryOptions 
}) => {
  const handleFilterChange = (filterType: string, value: string | number) => {
    setSearchOptions((prev: SearchOptions) => ({
      ...prev,
      [filterType]: value === "" ? null : filterType === 'rating' ? Number(value) : value
    }));
  }

  return (
    <div className="search-menu" id="search-menu">
      <form className='filter-form'>
        <label>
          Price:
          <select onChange={(e) => handleFilterChange('price', e.target.value)}>
            <option value="">Select a price</option>
            {priceOptions.map((price) => (
              <option key={price} value={price}>{'< '}{price}</option>
            ))}
          </select>
        </label>
        <label>
          Rating:
          <select onChange={(e) => handleFilterChange('rating', e.target.value)}>
            <option value="">Select a rating</option>
            {ratingOptions.map((rating) => (
              <option key={rating} value={rating}>{rating}+</option>
            ))}
          </select>
        </label>
        <label>
          Country:
          <select onChange={(e) => handleFilterChange('country', e.target.value)}>
            <option value="">Select a country</option>
            {countryOptions.map((country) => (
              <option key={country} value={country}>{country}</option>
            ))}
          </select>
        </label>
        <label>
          Search:
          <label className="input-buttons-menu">
            <input 
              placeholder="Type something..."
              onChange={(e) => setSearchOptions((prev: SearchOptions) => ({...prev, term: e.target.value}))}
            />
          </label>
        </label>
      </form>
    </div>
  );
};

export default FilterMenu;
